import { FilterRegistry } from 'domain/Filter';
import type { FilterForm } from 'models/Filters';

/**
 * Builds the query string for Watch Tower → Performance Tool / Commercial Results.
 * Maps `watch_tower_brand` to `brands` and keeps only shared context filters.
 * WatchTower-only dimensions (drivers, vehicles, channel, etc.) must not leak.
 */
export const buildWatchTowerExploreFurtherFilterQuery = (
  applied: FilterForm,
): string =>
  FilterRegistry.buildFilterQueryString(
    {
      zone: applied.zone,
      country: applied.country,
      periods: applied.periods,
      brands: applied.watch_tower_brand,
    },
    {
      kpis: applied.kpis,
      brand_filter_groupings: 'All Brands',
    },
  );
